/**
 * Write `packages/db/src/storage/index.ts` from what is in the directory.
 *
 * **The barrel is generated and is not in git** (`#271`). It grew from 2 exports
 * to 54 in six days across 49 commits — one `export *` per storage module, so
 * two agents adding two modules wrote two lines into the same file and merged
 * them by hand. A file nobody commits cannot be merged at all, which is the
 * whole of the fix: adding a storage module is now a change to exactly one file,
 * the module.
 *
 * It is regenerated by `npm run build`, which is the first step of `npm run
 * check` that needs it and runs before `typecheck` and `test`. `barrel.test.ts`
 * asserts that what is on disk is what this script writes.
 *
 * **It is deliberately not a root `prepare` hook.** It was, for one commit, and
 * it broke every image build: the Dockerfiles copy the `package.json` files and
 * run `npm ci` before copying any source, which is what makes the install layer
 * cacheable — and `prepare` then ran a script that was not in the image yet. A
 * lifecycle hook that needs source files does not belong on a step that
 * deliberately has none.
 *
 * The alternative was grouping the modules into subdirectories, one `export *`
 * per directory. It was not taken: `storage/x.ts` and `schema/x.ts` are a
 * deliberate pair today, and `schema/index.ts` cannot follow storage into
 * subdirectories because `drizzle-kit` reads it as one flat exhaustive list. The
 * two halves of this package would have stopped agreeing about their own shape,
 * and only one of them was free to move.
 */
import { readdir, readFile, writeFile } from 'node:fs/promises'
import process from 'node:process'
// `URL` and `process` are Node globals, imported rather than reached for: the
// eslint config declares no environment for this file, and a script is not worth
// a config block of its own.
import { fileURLToPath, URL } from 'node:url'

const STORAGE = fileURLToPath(new URL('../src/storage/', import.meta.url))
const BARREL = `${STORAGE}index.ts`

/**
 * Modules that are not re-exported wholesale, and why.
 *
 * `rows.ts` is the row-to-domain converter every storage module imports.
 * `toOwnSubmission` and `toTaskSubmission` are for its neighbours in this
 * directory and have never been part of what `@kolonie-ai/db` offers; an
 * `export *` here would put them there by accident. Any entry added below is a
 * claim that a module's file boundary and its public surface are different
 * things — worth writing down rather than assuming.
 */
const PARTIAL = {
  'rows.ts': ['toAgent', 'toSubmission', 'toTask', 'toTimestamp', 'toVerification'],
}

const HEADER = `/**
 * Every storage module, assembled by \`packages/db/scripts/generate-storage-barrel.mjs\`.
 *
 * **Generated, and deliberately not in git** (#271). Do not edit it and do not
 * add a line to it: a new storage module is picked up because it is in this
 * directory, which is what stops this file from being the append point two
 * agents collide in. Run \`npm run build\` (or \`npm install\`) to refresh it.
 *
 * A module whose public surface is narrower than its file is listed in the
 * generator's PARTIAL map, with the reason.
 */
`

/** Every module this directory offers: a `.ts` file, or a directory with its own barrel. */
export const storageEntries = async () => {
  const found = []

  for (const entry of await readdir(STORAGE, { withFileTypes: true })) {
    if (entry.isDirectory()) {
      const inner = await readdir(`${STORAGE}${entry.name}`)
      if (inner.includes('index.ts'))
        found.push({ name: entry.name, path: `./${entry.name}/index.js` })
      continue
    }
    if (!entry.name.endsWith('.ts')) continue
    if (entry.name.endsWith('.test.ts') || entry.name === 'index.ts') continue
    found.push({ name: entry.name, path: `./${entry.name.replace(/\.ts$/, '.js')}` })
  }

  // Sorted, because a generated file that reorders itself between runs is a diff
  // nobody asked for — and because this one is regenerated on every build.
  return found.sort((left, right) => left.name.localeCompare(right.name))
}

/** The barrel, as text. */
export const storageBarrel = async () => {
  const lines = (await storageEntries()).map((entry) => {
    const partial = PARTIAL[entry.name]
    return partial === undefined
      ? `export * from '${entry.path}'`
      : `export { ${partial.join(', ')} } from '${entry.path}'`
  })

  return `${HEADER}${lines.join('\n')}\n`
}

/** True when the file on disk is already what this script would write. */
export const barrelIsCurrent = async () => {
  const wanted = await storageBarrel()
  const found = await readFile(BARREL, 'utf8').catch(() => '')
  return { current: found === wanted, wanted, found }
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const { current, wanted } = await barrelIsCurrent()
  if (!current) await writeFile(BARREL, wanted)
}
